import {subjects} from '../../../lib/curriculum';
import {roster} from '../../../lib/mains-roster';
import {env} from 'cloudflare:workers';
import {getFaculty} from '../../../lib/faculty-auth';
import {HttpError,readJson,textField,failure} from '../../../lib/http';
import {defaults,dayKey} from '../../../lib/game';
const reply=(v:unknown,status=200)=>Response.json(v,{status,headers:{'Cache-Control':'no-store'}});
export async function GET(r:Request){return handle(r)}
export async function POST(r:Request){return handle(r)}
async function handle(r:Request){try{
if(r.method==='POST'&&(r.headers.get('origin')||r.headers.get('sec-fetch-site')==='cross-site'))throw new HttpError('Use the faculty website.',403);
const f=await getFaculty(r);if(!f)throw new HttpError('Faculty sign in required.',401);
const db=env.DB!,run=(sql:string,...v:any[])=>db.prepare(sql).bind(...v),rows=async(sql:string,...v:any[])=>(await run(sql,...v).all()).results as any[];
const b=r.method==='POST'?await readJson(r,1048576):{},action=b.action??'state';
const rules={...defaults,...JSON.parse((await run("SELECT value FROM config WHERE key='rules'").first<{value:string}>())?.value||'{}')};
const audit=(s:string)=>run('INSERT INTO audits VALUES(?,?,?,?)',crypto.randomUUID(),f.id,s,new Date().toISOString());
if(r.method==='POST'){const now=Date.now(),n=await run('INSERT INTO api_limits VALUES(?,1,?) ON CONFLICT(key) DO UPDATE SET count=count+1 RETURNING count','faculty:'+f.id+':'+Math.floor(now/60000),now+120000).first<{count:number}>();if(n!.count>120)throw new HttpError('Too many requests.',429);await run('DELETE FROM api_limits WHERE expires<?',now).run()}
const viewer=f.id==='22222';
if(viewer&&!['state','assignment-create','assignment-review','daily-challenge-create'].includes(action))throw new HttpError('Use a subject teacher account to manage the question bank.',403);
if(!viewer&&b.subject&&b.subject!==f.subject)throw new HttpError('Access is limited to your assigned subject.',403);
if(action==='daily-challenge-create'){
const subject=viewer?b.subject:f.subject;if(!subjects.some(s=>s.name===subject))throw new HttpError('Choose one of the six subjects.');
if(typeof b.day!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(b.day)||!Number.isFinite(Date.parse(b.day))||new Date(b.day+'T00:00:00Z').toISOString().slice(0,10)!==b.day||b.day<dayKey())throw new HttpError('Choose today or a future date.');
const title=textField(b.title,'Challenge title',120),instructions=typeof b.instructions==='string'?b.instructions.trim():'';if(instructions.length>3000)throw new HttpError('Instructions must be at most 3000 characters.');
if(!Array.isArray(b.questions)||b.questions.length<1)throw new HttpError('Add at least one question.');
const questions=b.questions.map((q:any)=>{if(!q||typeof q!=='object'||!Array.isArray(q.options)||q.options.length!==4||!Number.isInteger(q.answer)||q.answer<0||q.answer>3)throw new HttpError('Each question needs four options and a correct answer.');const options=q.options.map((v:unknown)=>textField(v,'Option',500));if(new Set(options.map((v:string)=>v.toLowerCase())).size!==4)throw new HttpError('Answer options must be distinct.');return {id:'faculty-'+crypto.randomUUID(),subject,topic:q.topic?textField(q.topic,'Topic',100):title,prompt:textField(q.prompt,'Question',2000),options,answer:q.answer,explanation:textField(q.explanation,'Explanation',3000)}});
const result=await db.batch([run(`INSERT OR IGNORE INTO daily_challenges(id,subject,day,title,instructions,questions,faculty,created) SELECT ?,?,?,?,?,?,?,? WHERE NOT EXISTS(SELECT 1 FROM attempts WHERE subject=? AND day=?)`,crypto.randomUUID(),subject,b.day,title,instructions,JSON.stringify(questions),f.id,new Date().toISOString(),subject,b.day),run('INSERT INTO audits SELECT ?,?,?,? WHERE changes()>0',crypto.randomUUID(),f.id,'Published daily challenge: '+title+' / '+b.day,new Date().toISOString())]);
if(!result[0].meta.changes)throw new HttpError('A challenge is already published or students have started this subject’s quiz. Choose another date.',409);return reply({ok:true})}
if(action==='assignment-create'){
const assignedSubject=viewer?b.subject:f.subject;if(!subjects.some(s=>s.name===assignedSubject))throw new HttpError('Choose one of the six assignment subjects.');
const title=textField(b.title,'Title',120),instructions=textField(b.instructions,'Instructions',5000);if(typeof b.due!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(b.due)||!Number.isFinite(Date.parse(b.due))||new Date(b.due+'T00:00:00Z').toISOString().slice(0,10)!==b.due)throw new HttpError('Choose a valid due date.');
await db.batch([run('INSERT INTO assignments VALUES(?,?,?,?,?,?)',crypto.randomUUID(),assignedSubject,title,instructions,b.due,new Date().toISOString()),audit('Published assignment: '+title)]);return reply({ok:true})}
if(action==='assignment-review'){
const id=textField(b.id,'Submission ID',100);const match=await run('SELECT s.id FROM submissions s JOIN assignments a ON a.id=s.assignment WHERE s.id=? AND (?=1 OR a.subject=?)',id,viewer?1:0,f.subject).first();if(!match)throw new HttpError('Submission not found in your subject.',404);
const result=await db.batch([run(`INSERT OR IGNORE INTO events SELECT ?,s.user,'assignment','assignment:'||s.assignment,?,?,?,NULL FROM submissions s JOIN assignments a ON a.id=s.assignment WHERE s.id=? AND s.reviewed IS NULL AND (?=1 OR a.subject=?)`,crypto.randomUUID(),rules.assignment,dayKey(),JSON.stringify({verifiedBy:f.id}),id,viewer?1:0,f.subject),run('UPDATE submissions SET reviewed=? WHERE id=? AND reviewed IS NULL',new Date().toISOString(),id),run('INSERT INTO audits SELECT ?,?,?,? WHERE changes()>0',crypto.randomUUID(),f.id,'Reviewed submission '+id,new Date().toISOString())]);if(!result[1].meta.changes)throw new HttpError('Already reviewed.',409);return reply({ok:true})}
if(action==='question'){
const topic=textField(b.topic,'Topic',100),prompt=textField(b.prompt,'Question',2000),explanation=textField(b.explanation,'Explanation',3000);if(!Array.isArray(b.options)||b.options.length!==4||!Number.isInteger(b.answer)||b.answer<0||b.answer>3)throw new HttpError('Provide four options and a correct answer.');const options=b.options.map((v:unknown)=>textField(v,'Option',500));if(new Set(options.map((v:string)=>v.toLowerCase())).size!==4)throw new HttpError('Options must be distinct.');await db.batch([run('INSERT INTO questions VALUES(?,?,?,?,?,?,?,0)',crypto.randomUUID(),f.subject,topic,prompt,JSON.stringify(options),b.answer,explanation),audit('Added question: '+topic)]);return reply({ok:true})}
if(action==='approve'){
if(typeof b.approved!=='boolean')throw new HttpError('Approval must be true or false.');const result=await db.batch([run('UPDATE questions SET approved=? WHERE id=? AND subject=?',b.approved?1:0,textField(b.id,'Question ID',100),f.subject),run('INSERT INTO audits SELECT ?,?,?,? WHERE changes()>0',crypto.randomUUID(),f.id,'Changed question approval',new Date().toISOString())]);if(!result[0].meta.changes)throw new HttpError('Question not found in your subject.',404);return reply({ok:true})}
if(action!=='state')throw new HttpError('Unknown action.');
const [assignments,submissions,people,questions,attempts,audits,challenges]=await Promise.all([rows('SELECT * FROM assignments WHERE (?=1 OR subject=?) ORDER BY created DESC',viewer?1:0,f.subject),rows('SELECT s.*,a.title,a.subject,p.name,p.campus FROM submissions s JOIN assignments a ON a.id=s.assignment JOIN people p ON p.id=s.user WHERE (?=1 OR a.subject=?) ORDER BY s.submitted DESC',viewer?1:0,f.subject),rows('SELECT id,name,campus,joined,avatar FROM people ORDER BY name'),rows('SELECT * FROM questions WHERE (?=1 OR subject=?) ORDER BY approved,topic',viewer?1:0,f.subject),rows("SELECT id,user,day,subject,answers,questions_snapshot,(SELECT e.xp FROM events e WHERE e.user=attempts.user AND e.kind='quiz' AND e.source=CASE WHEN attempts.subject='Mixed' THEN attempts.day ELSE attempts.day||':'||attempts.subject END AND e.void_reason IS NULL) AS xp FROM attempts WHERE submitted IS NOT NULL AND questions_snapshot IS NOT NULL AND EXISTS(SELECT 1 FROM events e WHERE e.user=attempts.user AND e.kind='quiz' AND e.source=CASE WHEN attempts.subject='Mixed' THEN attempts.day ELSE attempts.day||':'||attempts.subject END AND e.void_reason IS NULL)"),rows('SELECT action,created FROM audits WHERE actor=? ORDER BY created DESC LIMIT 30',f.id),rows('SELECT * FROM daily_challenges WHERE (?=1 OR subject=?) ORDER BY day DESC LIMIT 100',viewer?1:0,f.subject)]);
const activity:any[]=[];for(const a of attempts){const qs=JSON.parse(a.questions_snapshot),answers=JSON.parse(a.answers);const matching=qs.map((q:any,i:number)=>({q,i})).filter(({q}:any)=>viewer||q.subject===f.subject);if(matching.length)activity.push({id:a.id,subject:a.subject==='Mixed'?(viewer?'Mixed':f.subject):a.subject,xp:a.subject==='Mixed'?0:a.xp,user:a.user,day:a.day,total:matching.length,correct:matching.filter(({q,i}:any)=>answers[i]===q.answer).length})}
const rosterNames=new Map(roster.map(s=>[s.id,s.name]));
for(const p of people){p.displayName=p.name;p.name=rosterNames.get(p.id)||p.name}
for(const s of submissions)s.name=rosterNames.get(s.user)||s.name;
const students=people.map(p=>{const work=submissions.filter(s=>s.user===p.id),quiz=activity.filter(a=>a.user===p.id),total=quiz.reduce((n,a)=>n+a.total,0);return {...p,submitted:work.length,reviewed:work.filter(s=>s.reviewed).length,missing:Math.max(0,assignments.length-work.length),quizzes:quiz.length,quizXP:quiz.reduce((n,a)=>n+a.xp,0),accuracy:total?Math.round(100*quiz.reduce((n,a)=>n+a.correct,0)/total):null,last:[...work.map(s=>s.submitted.slice(0,10)),...quiz.map(a=>a.day)].sort().at(-1)||null}});
return reply({faculty:f,liveViewer:viewer,canManageAssignments:true,challenges:challenges.map(c=>({...c,questions:JSON.parse(c.questions)})),assignments,submissions,students,questions:questions.map(q=>({...q,options:JSON.parse(q.options)})),activity,audits,assignmentXP:rules.assignment,updatedAt:new Date().toISOString()});
}catch(e){return failure(e,reply)}}
